use leptos::prelude::*;

#[component]
pub fn Planning() -> impl IntoView {
    view! {
        <section class="school-planning wrap page-section" aria-labelledby="planning-title">
            <div class="section-heading"><div><p class="eyebrow">"FOR SCHOOLS, NEAR AND FAR"</p><h1 id="planning-title">"A little planning."<br/><span class="serif-line">"A world of possibility."</span></h1></div><p>"The practical details, all in one place. Neal travels internationally, bringing maps, stories, and live discovery to students around the world."</p></div>
            <div class="visit-facts" aria-label="Program at a glance"><div><span>"GRADE LEVELS"</span><strong>"Kindergarten–12"</strong></div><div><span>"PARTICIPATION"</span><strong>"30–90 suggested"</strong></div><div><span>"SCHOOL VISITS"</span><strong>"Worldwide"</strong></div></div>
            <div class="school-details-grid">
                <div class="planning-intro"><h2>"Built around your school day."</h2><p>"Neal has offered The Geography Gameshow since 2002. Each program is adapted to the grade level, combining maps drawn from memory with geography, history, and audience challenges."</p><p>"Start with your students, your location, and the subjects they are exploring. These details describe the Geography program; Anatomy and Art show formats are still in development."</p><a class="button" href="booking.html">"Start an inquiry"<span>"↗"</span></a><p class="planning-note">"Have a school outside the United States? You’re in the right place."</p></div>
                <div class="faq">
                    <details open><summary>"Scheduling & show length"<span>"+"</span></summary><div class="faq-content"><p>"Plan the day around your school routine. Allow at least 15 minutes between shows for students and materials to change over."</p><p>"Geography programs range from 30–45 minutes for kindergarten to 90–120 minutes for older students. Discuss the final schedule with Neal, including any classroom visits during longer breaks."</p></div></details>
                    <details><summary>"Room setup & materials"<span>"+"</span></summary><div class="faq-content"><ul><li>"White rolled paper and wall space for large drawings."</li><li>"Seating on the floor or in chairs with a clear view."</li><li>"A small table, scissors, and masking tape."</li><li>"A microphone, preferably a clip-on, for audiences over 150."</li></ul><p>"Your school keeps the maps to use in lessons, award to a student, or include in a fundraiser. Confirm the room and materials before the visit."</p></div></details>
                    <details><summary>"Audience size & participation"<span>"+"</span></summary><div class="faq-content"><p>"A group of 30–90 students per show is recommended to give more students a chance to take part. Larger audiences are welcome to discuss, with fewer individual opportunities to participate."</p><p>"Some students may be invited to answer questions or complete challenges. Prize tokens may be offered; schools can request to review them or ask for a different approach in advance. Teachers and staff help support student conduct throughout the show."</p></div></details>
                    <details><summary>"Lessons & school guidelines"<span>"+"</span></summary><div class="faq-content"><p>"Programs combine an introduction, live drawing, lesson connections, student participation, historical stories, and a conclusion. Content and format can be adapted to grade levels and specific classroom needs."</p><p>"Neal works with your school’s policies and expectations. Share accessibility needs, learning goals, or other requirements when planning the visit."</p></div></details>
                    <details><summary>"Photos, video & school media"<span>"+"</span></summary><div class="faq-content"><p>"Schools coordinate any necessary parent or guardian permissions for student images and media coverage. Short video excerpts may be shared on school websites; recording a full performance requires a prior arrangement with Neal."</p><p>"Please coordinate newspaper, newsletter, or television coverage with Neal and share copies of any published material. Feedback and letters of reference from teachers and administrators are welcome after the visit."</p></div></details>
                    <details><summary>"International school visits"<span>"+"</span></summary><div class="faq-content"><p>"Neal travels to schools around the world. Include your school’s country, full address, local phone number with country code, and possible dates in your inquiry."</p><p>"If several schools in your area are interested, mention that too. A coordinated schedule can help with planning an international visit."</p></div></details>
                </div>
            </div>
        </section>
    }
}
